    ('dores-musculares', 2, 'Vitamina C (ácido ascórbico)', 140, 'mg', 'vitamina-c', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Vitamina C", "forma_insumo": "Ácido ascórbico (CAS 50-81-7)", "massa_insumo_mg": 140.7035, "laudo_lote": "950467 (Analitic, fabricante 250306-C01)", "laudo_validade": "05/03/2029", "laudo_vencido": false, "teor_pct": 99.5, "teor_fonte": "laudo", "ativo_mg": 140, "unidade_ativo": "mg", "minimo": 13.5, "maximo": 1916.02, "pct_do_maximo": 7.31, "linha_anexo": "I·Ácido ascórbico/Ácido L-ascórbico; III/IV·Vitamina C", "status": "mantido", "e_sal": false, "observacao": "dose do rótulo (7,3% do teto)."}'),
    ('dores-musculares', 3, 'Magnésio (óxido de magnésio)', 70, 'mg', 'magnesio', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Magnésio", "forma_insumo": "Óxido de magnésio (MgO, CAS 1309-48-4) — insumo a adquirir", "massa_insumo_mg": 116.0782, "laudo_lote": null, "laudo_validade": null, "laudo_vencido": null, "teor_pct": 60.3, "teor_fonte": "assumido", "ativo_mg": 70, "unidade_ativo": "mg", "minimo": 63, "maximo": 350, "pct_do_maximo": 20.0, "linha_anexo": "I·Óxido de magnésio; III/IV·Magnésio", "status": "forma trocada + dose ajustada", "e_sal": false, "observacao": "100 mg de bisglicinato (laudo vencido) entregam 30,22 mg de Mg — 48% do mínimo de 63 mg. Para atingir o mínimo com folga (70 mg = 111% do mínimo; 20% do teto) o bisglicinato exigiria 231,6 mg, que não cabem; o óxido entrega 70 mg em 116,08 mg. Mesmo insumo novo proposto para Multivitamínico e Focus Colina."}'),
    ('dores-musculares', 4, 'Vitamina E (acetato de DL-alfa-tocoferol)', 20.3814, 'mg', 'vitamina-e', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Vitamina E", "forma_insumo": "Acetato de DL-alfa-tocoferol, pó 50% (CAS 7695-91-2)", "massa_insumo_mg": 60.0, "laudo_lote": "91320 (Analitic, fabricante 2025040605)", "laudo_validade": "05/04/2028", "laudo_vencido": false, "teor_pct": 50.7, "teor_fonte": "laudo", "ativo_mg": 20.3814, "unidade_ativo": "mg", "minimo": 2.25, "maximo": 1000, "pct_do_maximo": 2.04, "linha_anexo": "I·Acetato de DL-alfa-tocoferol; III/IV·Vitamina E (como α-tocoferol)", "status": "mantido (nome corrigido)", "e_sal": false, "observacao": "massa do memorial rev02 (60 mg de pó → 20,39 mg de α-tocoferol, 2,0% do teto). O rótulo nomeia ''DL-alfa-tocoferol''; o insumo real é o acetato — corrigir o nome."}'),
    ('dores-musculares', 5, 'Zinco (bisglicinato de zinco)', 10, 'mg', 'zinco', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Zinco", "forma_insumo": "Bisglicinato de zinco (CAS 14281-83-5)", "massa_insumo_mg": 50.2765, "laudo_lote": "055-ZN/25 (Galena, CIQ 2505027507)", "laudo_validade": "06/05/2027", "laudo_vencido": false, "teor_pct": 19.89, "teor_fonte": "laudo", "ativo_mg": 10, "unidade_ativo": "mg", "minimo": 1.65, "maximo": 29.59, "pct_do_maximo": 33.8, "linha_anexo": "I·Bisglicinato de zinco; III/IV·Zinco", "status": "mantido (declaração corrigida)", "e_sal": false, "observacao": "10 mg de zinco elemento (33,8% do teto), como a tabela nutricional do rótulo; a linha de composição dizia ''bisglicinato de zinco 10 mg'' (contradição sal × elemento). Memorial rev02 pesa 50,28 mg de sal — confirma o elemento."}'),
    ('dores-musculares', 6, 'Colágeno tipo II não desnaturado', 40, 'mg', 'colageno-tipo-ii-nao-desnaturado', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Colágeno tipo II não desnaturado", "forma_insumo": "Colágeno de frango com colágeno tipo II não desnaturado — PENDENTE ficha do fabricante (laudo Lepuge AUTO040251: ''COLAGENO T II'', fermentação biológica, proteína 67,60%, sem doseamento)", "massa_insumo_mg": 40.0, "laudo_lote": "AUTO040251 (Lepuge, fabricante CJ24110710)", "laudo_validade": "06/11/2026", "laudo_vencido": false, "teor_pct": null, "teor_fonte": "memorial", "ativo_mg": 40, "unidade_ativo": "mg", "minimo": 1.2, "maximo": null, "pct_do_maximo": null, "linha_anexo": "I·Colágeno de frango com colágeno tipo II não desnaturado (IN 76/2020); III·1,2 mg; IV·NE", "status": "mantido — PENDENTE identidade", "e_sal": false, "observacao": "40 mg (33× o mínimo). O Anexo I autoriza duas coisas distintas: ''Colágeno Tipo II'' em Proteínas (mín. 8,4 g) e ''colágeno de frango com colágeno tipo II não desnaturado'' (mín. 1,2 mg). O produto só é conforme no segundo enquadramento, e o laudo AUTO040251 (CAS 9007-34-5, ''fermentação biológica'', sem fabricante) não prova nem a origem em frango nem a forma não desnaturada. Sem a ficha do fabricante, retirar."}'),
    ('dores-musculares', 7, 'Ferro (bisglicinato ferroso)', 8, 'mg', 'ferro', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Ferro", "forma_insumo": "Bisglicinato ferroso (CAS 20150-34-9) — PENDENTE: o insumo pesado é ''Quelato Ferro Bios 20%'' (NaturalPRO NPT.0525/710), sem identidade química declarada", "massa_insumo_mg": 39.801, "laudo_lote": "NPT.0525/710 (NaturalPRO)", "laudo_validade": "05/2027", "laudo_vencido": false, "teor_pct": 20.1, "teor_fonte": "laudo", "ativo_mg": 8, "unidade_ativo": "mg", "minimo": 2.7, "maximo": 34.31, "pct_do_maximo": 23.32, "linha_anexo": "I·Bisglicinato ferroso; III/IV·Ferro", "status": "mantido — PENDENTE identidade", "e_sal": false, "observacao": "8 mg de ferro elemento (23,3% do teto), como a tabela nutricional do rótulo (a composição dizia ''bisglicinato de ferro 8 mg'', ambíguo). O laudo NaturalPRO chama o produto de ''Quelato Ferro Bios 20%'' e cita a Farmacopeia Brasileira 6ª ed., mas não diz que é bisglicinato ferroso nem traz CAS; os únicos laudos de bisglicinato ferroso da máquina estão vencidos (2022 e 2023). Sem declaração do fabricante, comprar bisglicinato ferroso com laudo."}'),
    ('dores-musculares', 8, 'Vitamina D3 (colecalciferol)', 40, 'mcg', 'vitamina-d', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Vitamina D", "forma_insumo": "Vitamina D3 (colecalciferol), pó 100.000 UI/g (CAS 67-97-0)", "massa_insumo_mg": 13.913, "laudo_lote": "91408 (Analitic, fabricante 2025111601)", "laudo_validade": "15/11/2028", "laudo_vencido": false, "teor_pct": null, "teor_fonte": "laudo", "ativo_mg": 0.04, "unidade_ativo": "µg", "minimo": 3, "maximo": 50.0, "pct_do_maximo": 80.0, "linha_anexo": "I·Vitamina D3 (Colecalciferol); III/IV·Vitamina D", "status": "dose ajustada", "e_sal": false, "observacao": "50 µg era o teto exato; nova dose 40 µg (80,0%; 267% do VD). O rótulo vigente imprime ''50 mg'' na tabela nutricional (erro de mil vezes) e %VD 1000% pelo VDR revogado — corrigir."}'),
    ('dores-musculares', 9, 'Vitamina B6 (cloridrato de piridoxina)', 1.3, 'mg', 'vitamina-b6', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Vitamina B6", "forma_insumo": "Cloridrato de piridoxina (CAS 58-56-0)", "massa_insumo_mg": 1.5817, "laudo_lote": "91188 (Analitic, fabricante 241229T092)", "laudo_validade": "28/12/2027", "laudo_vencido": false, "teor_pct": 99.9, "teor_fonte": "laudo", "ativo_mg": 1.3, "unidade_ativo": "mg", "minimo": 0.26, "maximo": 98.6, "pct_do_maximo": 1.32, "linha_anexo": "I·Cloridrato de piridoxina; III/IV·Vitamina B6", "status": "mantido", "e_sal": false, "observacao": "dose do rótulo (1,3% do teto)."}'),
    ('dores-musculares', 10, 'Selênio (selenito de sódio)', 100, 'mcg', 'selenio', '{"fonte": "reformulacao_2026-09-16", "constituinte_anexo_i": "Selênio", "forma_insumo": "Selenito de sódio (CAS 10102-18-8) — insumo a adquirir", "massa_insumo_mg": 0.219, "laudo_lote": null, "laudo_validade": null, "laudo_vencido": null, "teor_pct": 45.66, "teor_fonte": "assumido", "ativo_mg": 0.1, "unidade_ativo": "µg", "minimo": 8.25, "maximo": 319.75, "pct_do_maximo": 31.27, "linha_anexo": "I·Selenito de sódio; III/IV·Selênio", "status": "forma trocada", "e_sal": false, "observacao": "''selênio quelado'' (glicinato de selênio, lote 044152 — laudo lido por imagem) não é forma do Anexo I. Dose do rótulo (31,3% do teto)."}'),
